// ===== Edit your settings here =====
return [{
  json: {
    // arXiv API search_query syntax: https://info.arxiv.org/help/api/user-manual.html#query_details
    arxivQuery: "(cat:cs.CL OR cat:cs.LG OR cat:cs.AI OR cat:cs.SE) AND (abs:\"weight-space programming\" OR abs:\"weight space programming\" OR abs:\"knowledge editing\" OR abs:\"model editing\" OR abs:\"locate-then-edit\" OR abs:\"lifelong editing\" OR abs:\"sequential editing\" OR abs:\"intra-weight\" OR abs:\"weight differences\" OR abs:\"code knowledge\" OR (abs:\"code translation\" AND abs:\"LLM\"))",
    arxivMaxResults: 100,
    // Semantic Scholar paperIds: new papers citing these are collected
    keyPapers: [
      {
            "id": "565be60314d70a665f6cf7c38e33540ecf7e3726",
            "title": "Exploring Weight-Space Programming"
      },
      {
            "id": "a749cbb0459e56049b360dfb38161f132ee421f1",
            "title": "IWIBench"
      },
      {
            "id": "3d92afe312072d0b1008c16cdeb81e52baa59894",
            "title": "Xue et al. (TCPE / KECode)"
      },
      {
            "id": "3a716fc45fe6233a29f58ad492e21d690d9054a0",
            "title": "Gupta et al. 2024 (forgetting)"
      },
      {
            "id": "c1d88b0d9499eb4b105af1253c6367e6c4af497b",
            "title": "Interpreting Weight Differences"
      },
      {
            "id": "0251bb95be75d472c8d5b873751615e7fe2feb1d",
            "title": "Zhang et al. 2024 (KE survey)"
      },
      {
            "id": "996445d847f06e99b0bd259345408a0cf1bce87e",
            "title": "ROME"
      },
      {
            "id": "2fe1ac0b09cc0f50eb83eef6c7c6b45ac8b12413",
            "title": "MEMIT"
      }
    ],
    lookbackDays: 14,       // ignore papers published before this
    minScore: 4,            // only papers scoring >= this go into the digest
    model: 'claude-opus-5-5',
    thesis: "You help a master's student monitor new literature for their thesis.\n\nTHESIS\nCan LLM-based weight-space editing (\"weight-space programming\") improve a\nmodel's knowledge and behaviour more effectively and with less collateral\ndamage than conventional knowledge-editing methods?\n\n- Weight-space programming: neural network weights are serialized as text and\n  given to an LLM, which interprets and directly modifies them.\n- Baselines: conventional knowledge editing such as ROME, MEMIT and MEND\n  (causal tracing / locate-then-edit, mass editing, learned gradient-based\n  editors), and their known failure modes: degrading effectiveness and\n  gradual/catastrophic forgetting under sequential edits.\n- Application: correcting code-generation errors in Java-to-D code\n  translation, evaluated with KECode-style metrics (editing efficacy,\n  collateral damage / locality, generalization to unseen examples).\n- Experiments: small models first, then ~8B models with only selected layers\n  or MLP weights exposed to the LLM.\n\nHIGHLY RELEVANT: weight-space programming / LLMs reading or editing weights;\ninterpreting weight differences; gradient-free or intra-weight editing;\nknowledge/model editing methods, benchmarks and evaluations; sequential or\nlifelong editing and forgetting; editing code knowledge; code-to-code\ntranslation with LLMs (especially low-resource target languages).\nLESS RELEVANT: general fine-tuning, RAG, generic interpretability without an\nediting angle, weight-space work in unrelated domains (e.g. medical imaging)\nunless the method transfers.\n\nTASK\nRate how relevant the given paper is to this thesis:\n5 = directly addresses the research question or a core method/baseline\n4 = closely related, likely worth reading\n3 = same broader area, maybe useful for background\n2 = tangentially related\n1 = not relevant\nGive the score and one short sentence explaining how the paper relates to\nthe thesis (mention the specific connection, not a summary of the paper).",
  },
}];

const xml = $input.first().json.data ?? '';
const cfg = $('Config').first().json;
const cutoff = Date.now() - cfg.lookbackDays * 864e5;

const decode = (s) => s.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'").replace(/&amp;/g, '&');
const clean = (s) => decode(s || '').replace(/\s+/g, ' ').trim();
const get = (block, tag) => {
  const m = block.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`));
  return m ? clean(m[1]) : '';
};

const out = [];
for (const m of xml.matchAll(/<entry>([\s\S]*?)<\/entry>/g)) {
  const e = m[1];
  const arxivId = get(e, 'id').replace(/^.*\/abs\//, '').replace(/v\d+$/, '');
  const published = get(e, 'published');
  if (!arxivId || new Date(published).getTime() < cutoff) continue;
  out.push({
    json: {
      key: `arxiv:${arxivId.toLowerCase()}`,
      arxivId,
      title: get(e, 'title'),
      abstract: get(e, 'summary'),
      authors: [...e.matchAll(/<name>([\s\S]*?)<\/name>/g)].map((a) => clean(a[1])),
      published: published.slice(0, 10),
      url: `https://arxiv.org/abs/${arxivId}`,
      source: 'arXiv search',
    },
  });
}
return out;

const cfg = $('Config').first().json;
const keyPapers = $('Key papers').all().map((i) => i.json);
const cutoff = Date.now() - cfg.lookbackDays * 864e5;

const out = [];
$input.all().forEach((item, i) => {
  const via = keyPapers[i]?.title ?? 'key paper';
  for (const c of item.json.data ?? []) {
    const p = c.citingPaper;
    // skip papers without a date: they would flood the first run with old work
    if (!p?.title || !p.publicationDate) continue;
    if (new Date(p.publicationDate).getTime() < cutoff) continue;
    const arxivId = p.externalIds?.ArXiv ?? null;
    out.push({
      json: {
        key: arxivId ? `arxiv:${arxivId.toLowerCase()}` : `s2:${p.paperId}`,
        arxivId,
        title: p.title,
        abstract: p.abstract ?? '',
        authors: (p.authors ?? []).map((a) => a.name),
        published: p.publicationDate,
        url: arxivId ? `https://arxiv.org/abs/${arxivId}` : p.url,
        source: `cites ${via}`,
      },
    });
  }
});
return out;

// Merge duplicates within this run (same arXiv id or same title)
const byKey = new Map();
const records = [];
for (const { json: p } of $input.all()) {
  const titleKey = p.title.toLowerCase().replace(/[^a-z0-9]/g, '');
  const existing = byKey.get(p.key) ?? byKey.get(titleKey);
  if (existing) {
    if (!existing.sources.includes(p.source)) existing.sources.push(p.source);
    if (!existing.abstract && p.abstract) existing.abstract = p.abstract;
    continue;
  }
  const { source, ...rest } = p;
  const rec = { ...rest, titleKey, sources: [source] };
  byKey.set(p.key, rec);
  byKey.set(titleKey, rec);
  records.push(rec);
}
return records.map((json) => ({ json }));

const cfg = $('Config').first().json;

return $input.all().map(({ json: p }) => ({
  json: {
    paper: p,
    body: {
      model: cfg.model,
      max_tokens: 2000,
      // Thinking is always on for this model; low effort is enough for scoring
      output_config: {
        effort: 'low',
        format: {
          type: 'json_schema',
          schema: {
            type: 'object',
            properties: {
              score: { type: 'integer', description: 'Relevance 1-5' },
              reason: { type: 'string' },
            },
            required: ['score', 'reason'],
            additionalProperties: false,
          },
        },
      },
      // If the model declines, the API retries on a fallback model in the same call
      fallbacks: 'default',
      system: cfg.thesis,
      messages: [{
        role: 'user',
        content: [
          `Title: ${p.title}`,
          `Authors: ${(p.authors ?? []).slice(0, 8).join(', ')}`,
          `Found via: ${p.sources.join('; ')}`,
          `Abstract: ${p.abstract || '(no abstract available - judge from the title)'}`,
        ].join('\n'),
      }],
    },
  },
}));

const requests = $('Build LLM request').all();

return $input.all().map((item, i) => {
  const paper = requests[i].json.paper;
  let score = null;
  let reason = '';
  try {
    const res = item.json;
    if (res.error) throw new Error(res.error.message ?? JSON.stringify(res.error));
    if (res.stop_reason === 'refusal') throw new Error('model declined');
    const text = (res.content ?? []).filter((b) => b.type === 'text').map((b) => b.text).join('');
    const parsed = JSON.parse(text);
    score = Math.max(1, Math.min(5, Number(parsed.score)));
    reason = parsed.reason;
  } catch (e) {
    reason = `scoring failed: ${e.message}`;
  }
  return { json: { ...paper, score, reason } };
});

const cfg = $('Config').first().json;
const all = $input.all().map((i) => i.json);
const relevant = all.filter((p) => p.score >= cfg.minScore).sort((a, b) => b.score - a.score);
const failed = all.filter((p) => p.score === null);

if (!relevant.length && !failed.length) return [];

// escape Discord markdown in titles etc.
const md = (s) => String(s ?? '').replace(/([\\*_~`|\[\]>])/g, '\\$1');
const date = new Date().toISOString().slice(0, 10);

let header = `**Paper digest ${date}**\n${relevant.length} relevant of ${all.length} new papers`;
if (failed.length) header += `\n${failed.length} could not be scored (${md(failed[0].reason)})`;
header += '\n';

const blocks = relevant.map((p) =>
  `\n${'★'.repeat(p.score)} [${md(p.title)}](<${p.url}>)\n` +
  `*${md(p.reason)}*\n` +
  `-# ${md(p.sources.join(' · '))}\n`);

// Discord messages max out at 2000 chars
const messages = [];
let current = header;
for (const b of blocks) {
  if ((current + b).length > 1900) { messages.push(current); current = ''; }
  current += b;
}
messages.push(current);
return messages.map((text) => ({ json: { text } }));
